// The Codex (O433 phase 5, track Q): an in-client encyclopedia of the item system. Tabs (Modifiers, Powers, Orbs, Gems, Uniques, Sets, Rift, Supports,
// Materials, Basics, Lore), a search box (every word must start a word of the name or the page), the tab's filters (side, item kind, item level, level, group),
// the list of entries and the page of the chosen one. No server round trip: everything is Resources/Codex.json, generated by unity/tools/gen_info_data.lua
// from the main client's codex_data.lua (which server/tools/gen_codex_data.lua writes from the server's data files).
// A port of game_codex/codexview.lua (the logic that needs no client API); the window is Unity/Windows/CodexWindow.cs. The texts stay English: the main client
// translates them through its own key table (CodexText), which Unity does not have.
//   section = {h, p [paragraphs], cols, w, rows [[cells]], links [entry id | ""], tiers (rows are T1..T8: the item level filter marks the ones that roll)} | {ref}
// Tests: Core.Tests/InfoTests.cs (mirrors codexview_test.lua).
using System;
using System.Collections.Generic;
using System.Globalization;
using System.Text;

namespace Chaos.Core
{
    public sealed class CodexSection
    {
        public string Ref = "", H = "";
        public List<string> Paragraphs = new List<string>(), Cols = new List<string>();
        public List<double> W = new List<double>();
        public List<List<string>> Rows;
        public List<string> Links;
        public bool Tiers;
    }

    public sealed class CodexOption { public string Value = "", Text = ""; }

    public sealed class CodexFilter
    {
        public string Key = "", Label = "", Match = "eq";
        public readonly List<CodexOption> Options = new List<CodexOption>();
    }

    public sealed class CodexEntry
    {
        public string Id = "", Name = "", Color = "", Sub = "", Art = "";
        public Dictionary<string, object> F = new Dictionary<string, object>();
        public List<string> Tv;
        public readonly List<CodexSection> Sections = new List<CodexSection>();
        public readonly List<int> Items = new List<int>();
        string search;
        public string SearchCache { get { return search; } set { search = value; } }
    }

    public sealed class CodexTab
    {
        public string Id = "", Name = "";
        public readonly List<CodexFilter> Filters = new List<CodexFilter>();
        public readonly List<CodexEntry> Entries = new List<CodexEntry>();
    }

    public sealed class CodexData
    {
        public readonly List<string> Rarities = new List<string>();
        public int[] TierLevels = new int[0], TierWeights = new int[0];
        public int TierWindow = 5;
        public readonly Dictionary<string, CodexSection> Shared = new Dictionary<string, CodexSection>();
        public readonly List<CodexTab> Tabs = new List<CodexTab>();

        public bool Ready => Tabs.Count > 0;

        static List<string> Strings(object o, string key)
        {
            var l = new List<string>();
            foreach (object x in Json.List(o, key)) l.Add(x as string ?? (x is double d ? d.ToString(CultureInfo.InvariantCulture) : ""));
            return l;
        }

        static CodexSection Section(object o)
        {
            var s = new CodexSection { Ref = Json.Text(o, "ref"), H = Json.Text(o, "h"), Tiers = Json.Bool(o, "tiers") };
            s.Paragraphs = Strings(o, "p");
            s.Cols = Strings(o, "cols");
            foreach (object w in Json.List(o, "w")) if (w is double d) s.W.Add(d);
            if (Json.Get(o, "rows") is List<object> rows)
            {
                s.Rows = new List<List<string>>();
                foreach (object r in rows)
                {
                    var cells = new List<string>();
                    if (r is List<object> rl) foreach (object c in rl) cells.Add(c as string ?? (c is double d ? d.ToString(CultureInfo.InvariantCulture) : ""));
                    s.Rows.Add(cells);
                }
            }
            if (Json.Get(o, "links") is List<object>) s.Links = Strings(o, "links");
            return s;
        }

        public static CodexData Load(string jsonText)
        {
            var d = new CodexData();
            object root = Json.TryParse(jsonText);
            if (!(root is Dictionary<string, object>)) return d;
            d.Rarities.AddRange(Strings(root, "rarities"));
            var tl = Json.List(root, "tierLevels"); d.TierLevels = new int[tl.Count];
            for (int i = 0; i < tl.Count; i++) d.TierLevels[i] = tl[i] is double a ? (int)a : 0;
            var tw = Json.List(root, "tierWeights"); d.TierWeights = new int[tw.Count];
            for (int i = 0; i < tw.Count; i++) d.TierWeights[i] = tw[i] is double a ? (int)a : 1;
            d.TierWindow = Math.Max(1, Json.Int(root, "tierWindow", 5));
            if (Json.Get(root, "shared") is Dictionary<string, object> shared) foreach (var kv in shared) d.Shared[kv.Key] = Section(kv.Value);
            foreach (object t in Json.List(root, "tabs"))
            {
                var tab = new CodexTab { Id = Json.Text(t, "id"), Name = Json.Text(t, "name") };
                foreach (object f in Json.List(t, "filters"))
                {
                    var flt = new CodexFilter { Key = Json.Text(f, "key"), Label = Json.Text(f, "label"), Match = Json.Text(f, "match") };
                    foreach (object o in Json.List(f, "options"))
                        if (o is List<object> pair && pair.Count >= 2) flt.Options.Add(new CodexOption { Value = pair[0] as string ?? "", Text = pair[1] as string ?? "" });
                    tab.Filters.Add(flt);
                }
                foreach (object e in Json.List(t, "entries"))
                {
                    var en = new CodexEntry { Id = Json.Text(e, "id"), Name = Json.Text(e, "name"), Color = Json.Text(e, "color"), Sub = Json.Text(e, "sub"), Art = Json.Text(e, "art") };
                    if (Json.Get(e, "f") is Dictionary<string, object> fd) en.F = fd;
                    if (Json.Get(e, "tv") is List<object>) en.Tv = Strings(e, "tv");
                    foreach (object s in Json.List(e, "sections")) en.Sections.Add(Section(s));
                    foreach (object it in Json.List(e, "items")) if (it is double id) en.Items.Add((int)id);
                    tab.Entries.Add(en);
                }
                d.Tabs.Add(tab);
            }
            return d;
        }

        public int EntryCount { get { int n = 0; foreach (var t in Tabs) n += t.Entries.Count; return n; } }
    }

    /// <summary>The Codex window's logic: search, filters, the item level view of a modifier's tiers, shared sections, finding an entry, column widths.</summary>
    public static class CodexView
    {
        /// <summary>Lower-case words of a search.</summary>
        public static List<string> Tokens(string query)
        {
            var o = new List<string>();
            foreach (var w in (query ?? "").ToLowerInvariant().Split((char[])null, StringSplitOptions.RemoveEmptyEntries)) o.Add(w);
            return o;
        }

        /// <summary>A section, or the shared one it refers to (null when the reference is unknown).</summary>
        public static CodexSection Section(CodexSection s, CodexData data)
        {
            if (s != null && s.Ref.Length > 0)
            {
                CodexSection shared;
                return data != null && data.Shared.TryGetValue(s.Ref, out shared) ? shared : null;
            }
            return s;
        }

        /// <summary>Everything a search looks at (name, line, every text of the page), lower case.</summary>
        public static string SearchText(CodexEntry e, CodexData data)
        {
            if (e.SearchCache != null) return e.SearchCache;
            var sb = new StringBuilder();
            sb.Append(e.Name).Append('\n').Append(e.Sub);
            foreach (var raw in e.Sections)
            {
                var s = Section(raw, data);
                if (s == null) continue;
                sb.Append('\n').Append(s.H);
                foreach (var p in s.Paragraphs) sb.Append('\n').Append(p);
                if (s.Rows != null) foreach (var r in s.Rows) foreach (var c in r) sb.Append('\n').Append(c);
            }
            e.SearchCache = sb.ToString().ToLowerInvariant();
            return e.SearchCache;
        }

        static bool IsAlnum(char c) => (c >= '0' && c <= '9') || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');

        /// <summary>A search word matches the start of a word of the text ("kill" finds "Life on Kill", not "Skill"); a word that starts with a sign or a digit matches anywhere.</summary>
        public static bool HasWord(string text, string word)
        {
            if (word.Length == 0) return true;
            bool alpha = (word[0] >= 'a' && word[0] <= 'z') || (word[0] >= 'A' && word[0] <= 'Z');
            int from = 0;
            while (true)
            {
                int i = text.IndexOf(word, from, StringComparison.Ordinal);
                if (i < 0) return false;
                if (!alpha || i == 0 || !IsAlnum(text[i - 1])) return true;
                from = i + 1;
            }
        }

        /// <summary>One filter: a value of "" passes everything; eq the entry's field equals it, has the entry's list holds it, max the entry's number is at most it, ilvl changes only the list.</summary>
        public static bool Passes(CodexEntry e, CodexFilter f, string value)
        {
            if (string.IsNullOrEmpty(value) || f.Match == "ilvl") return true;
            object field;
            e.F.TryGetValue(f.Key, out field);
            if (f.Match == "has")
            {
                if (field is List<object> list) { foreach (object x in list) if (x is string s && s == value) return true; return false; }
                return field is string fs && fs == value;
            }
            if (f.Match == "max")
            {
                double n, limit;
                bool a = field is double ? (n = (double)field) == n : double.TryParse(field as string, NumberStyles.Float, CultureInfo.InvariantCulture, out n);
                bool b = double.TryParse(value, NumberStyles.Float, CultureInfo.InvariantCulture, out limit);
                return a && b && n <= limit;
            }
            return field is string eq && eq == value;
        }

        public static bool Matches(CodexEntry e, IList<CodexFilter> filters, IDictionary<string, string> values, IList<string> words, CodexData data)
        {
            foreach (var f in filters)
            {
                string v;
                if (!Passes(e, f, values != null && values.TryGetValue(f.Key, out v) ? v : null)) return false;
            }
            if (words != null && words.Count > 0)
            {
                string text = SearchText(e, data);
                foreach (var w in words) if (!HasWord(text, w)) return false;
            }
            return true;
        }

        /// <summary>The entries of a tab that pass the search and the filters.</summary>
        public static List<CodexEntry> List(CodexTab tab, string query, IDictionary<string, string> values, CodexData data)
        {
            var words = Tokens(query);
            var o = new List<CodexEntry>();
            if (tab == null) return o;
            foreach (var e in tab.Entries) if (Matches(e, tab.Filters, values, words, data)) o.Add(e);
            return o;
        }

        // ------------------------------------------------------------------------------------ tiers (the same rules as the server's chaos_item_mods.lua)
        public static int MaxTier(int level, CodexData d)
        {
            int best = 1;
            for (int t = 1; t <= d.TierLevels.Length; t++) if (level >= d.TierLevels[t - 1]) best = t;
            return best;
        }

        /// <summary>The tiers that roll at an item level, best first, with their weights.</summary>
        public static List<KeyValuePair<int, int>> TierRows(int level, CodexData d)
        {
            int top = MaxTier(level, d);
            var rows = new List<KeyValuePair<int, int>>();
            for (int t = top; t >= Math.Max(1, top - d.TierWindow + 1); t--) rows.Add(new KeyValuePair<int, int>(t, t - 1 < d.TierWeights.Length ? d.TierWeights[t - 1] : 1));
            return rows;
        }

        /// <summary>The chance of each rolling tier in percent with one decimal.</summary>
        public static Dictionary<int, double> TierChances(int level, CodexData d)
        {
            var rows = TierRows(level, d);
            double total = 0;
            foreach (var r in rows) total += r.Value;
            var o = new Dictionary<int, double>();
            foreach (var r in rows) o[r.Key] = Math.Floor(r.Value * 1000.0 / total + 0.5) / 10;
            return o;
        }

        /// <summary>The item level chosen in the tab's "ilvl" filter, or null.</summary>
        public static int? LevelOf(IDictionary<string, string> values, IList<CodexFilter> filters)
        {
            foreach (var f in filters)
            {
                string v;
                int n;
                if (f.Match == "ilvl" && values != null && values.TryGetValue(f.Key, out v) && int.TryParse(v, NumberStyles.Integer, CultureInfo.InvariantCulture, out n)) return n;
            }
            return null;
        }

        /// <summary>The list line: the entry's own, or its tiers at the chosen level.</summary>
        public static string Subline(CodexEntry e, int? level, CodexData d)
        {
            if (!level.HasValue || e.Tv == null || d == null) return CodexText.Sub(e.Sub);
            var rows = TierRows(level.Value, d);
            int hi = rows[0].Key, lo = rows[rows.Count - 1].Key;
            string tv(int t) => t - 1 < e.Tv.Count ? e.Tv[t - 1] : "";
            string range = lo == hi ? "T" + hi + " " + tv(hi) : "T" + lo + "-T" + hi + ": " + tv(lo) + " to " + tv(hi);
            return Loc.T("Item level {0}: {1}", level.Value, range);
        }

        /// <summary>The tier rows of a table that roll at the chosen level (marked on the page).</summary>
        public static HashSet<int> Highlight(CodexSection s, int? level, CodexData d)
        {
            var o = new HashSet<int>();
            if (s == null || !s.Tiers || !level.HasValue || d == null) return o;
            foreach (var r in TierRows(level.Value, d)) o.Add(r.Key);
            return o;
        }

        /// <summary>The tab index and entry of an id (-1, null when unknown).</summary>
        public static CodexEntry Find(CodexData d, string id, out int tabIndex)
        {
            tabIndex = -1;
            if (d == null) return null;
            for (int i = 0; i < d.Tabs.Count; i++)
                foreach (var e in d.Tabs[i].Entries) if (e.Id == id) { tabIndex = i; return e; }
            return null;
        }

        /// <summary>A modifier as the crafting bench names it (attribute key, group) to the id of its page, or null.</summary>
        public static string IdForMod(string key, string group, CodexData d)
        {
            key = (key ?? "").ToLowerInvariant();
            if (key.Length == 0) return null;
            var candidates = new List<string>();
            if (group == "rift") candidates.Add("rift:" + key);
            else
            {
                candidates.Add("mod:" + key);
                candidates.Add("power:" + (key.StartsWith("chaos_mod_") ? key.Substring(10) : key));
            }
            foreach (var id in candidates) { int t; if (Find(d, id, out t) != null) return id; }
            return null;
        }

        /// <summary>Column widths in pixels from relative widths: each at least 1, together exactly total minus the gaps.</summary>
        public static int[] Columns(IList<double> w, double total, double gap)
        {
            int n = w.Count;
            if (n == 0) return new int[0];
            double free = Math.Max(n, total - gap * (n - 1)), sum = 0;
            foreach (var x in w) sum += Math.Max(0, x);
            var o = new int[n];
            int used = 0;
            for (int i = 0; i < n; i++)
            {
                double share = sum > 0 ? Math.Max(0, w[i]) / sum : 1.0 / n;
                o[i] = (int)Math.Max(1, Math.Floor(free * share));
                used += o[i];
            }
            o[n - 1] = (int)Math.Max(1, o[n - 1] + free - used);
            return o;
        }
    }
}
